# ============================================================
# 02_plot_prediction_overlap_upset.R
#
# Aim
# ---
# Visualise overlap between annotated candidate targets predicted
# by CopraRNA, IntaRNA and TargetRNA2 using an UpSet plot.
#
# The script uses the harmonised annotated output generated by:
#
#   01_harmonise_target_predictions.R
#
# Target identity has therefore already been resolved by reference
# locus before this script is run.
#
#
# INPUT
# -----
# results/tables/target_prediction_overlap_annotated.csv
#
# Expected columns:
#
#   candidate_id
#   reference_locus
#   gene
#   annotation
#   CopraRNA
#   TargetRNA2
#   IntaRNA
#   n_methods
#
#
# OUTPUTS
# -------
# results/tables/target_prediction_intersection_counts.csv
# results/tables/targets_by_prediction_group.csv
# results/tables/targets_predicted_by_all_three_methods.csv
#
# results/figures/target_prediction_upset.pdf
# results/figures/target_prediction_upset.tiff
#
#
# RUNNING THE SCRIPT
# ------------------
# 1. Run 01_harmonise_target_predictions.R.
# 2. Confirm that target_prediction_overlap_annotated.csv exists.
# 3. Run this script from the repository root.
#
# To analyse the complete, unfiltered set later, change only:
#
#   target_prediction_overlap_annotated.csv
#
# to:
#
#   target_prediction_overlap_all.csv
#
# ============================================================



# ============================================================
# USER SETTINGS
# ============================================================

# Set the working directory to the root of the analysis project
# before running this script.
#
# Example:
# setwd("/path/to/sRNA-target-pipeline")

project_dir <- getwd()


# Names used in the harmonised input table.

prediction_methods <- c(
  "CopraRNA",
  "TargetRNA2",
  "IntaRNA"
)


# Colours used for each prediction method.

tool_colours <- c(
  "CopraRNA"   = "#F8766D",
  "TargetRNA2" = "#7CAE00",
  "IntaRNA"    = "#00BFC4"
)


# Figure dimensions.

figure_width <- 8.5

figure_height <- 5.8

figure_dpi <- 600


# Optional figure title and subtitle.

figure_title <-
  "Overlap between GcvB target-prediction methods"


figure_subtitle <-
  paste(
    "Annotated candidate loci predicted by",
    "CopraRNA, TargetRNA2 and IntaRNA"
  )



# ============================================================
# PACKAGES
# ============================================================

required_pkgs <- c(
  "readr",
  "dplyr",
  "ComplexUpset",
  "ggplot2",
  "patchwork"
)


missing_pkgs <- required_pkgs[
  !vapply(
    required_pkgs,
    requireNamespace,
    quietly = TRUE,
    FUN.VALUE = logical(1)
  )
]


if (length(missing_pkgs) > 0) {
  
  install.packages(
    missing_pkgs
  )
}


suppressPackageStartupMessages({
  
  library(readr)
  
  library(dplyr)
  
  library(ComplexUpset)
  
  library(ggplot2)
  
  library(patchwork)
  
})



# ============================================================
# PATHS
# ============================================================

project_dir <- getwd()


input_file <- file.path(
  project_dir,
  "results",
  "tables",
  "target_prediction_overlap_annotated.csv"
)


table_dir <- file.path(
  project_dir,
  "results",
  "tables"
)


figure_dir <- file.path(
  project_dir,
  "results",
  "figures"
)


dir.create(
  table_dir,
  recursive = TRUE,
  showWarnings = FALSE
)


dir.create(
  figure_dir,
  recursive = TRUE,
  showWarnings = FALSE
)



# ============================================================
# CHECK INPUT
# ============================================================

if (!file.exists(input_file)) {
  
  stop(
    "Input file not found:\n",
    input_file,
    "\n\nRun 01_harmonise_target_predictions.R first."
  )
}



# ============================================================
# IMPORT HARMONISED TARGET MEMBERSHIP
# ============================================================

targets <- read_csv(
  input_file,
  show_col_types = FALSE
)



required_columns <- c(
  "candidate_id",
  "reference_locus",
  "gene",
  "annotation",
  prediction_methods,
  "n_methods"
)


missing_columns <- setdiff(
  required_columns,
  names(targets)
)


if (length(missing_columns) > 0) {
  
  stop(
    "Input table is missing required column(s):\n",
    paste(
      missing_columns,
      collapse = ", "
    )
  )
}



# ============================================================
# STANDARDISE METHOD COLUMNS
# ============================================================

# Method membership should be TRUE/FALSE.

targets <- targets %>%
  mutate(
    across(
      all_of(prediction_methods),
      as.logical
    )
  )



# ============================================================
# BASIC QC
# ============================================================

if (
  anyDuplicated(
    targets$reference_locus
  ) > 0
) {
  
  stop(
    "Duplicate reference loci were found in the overlap input table."
  )
}



cat(
  "\n============================================\n",
  "Prediction-overlap analysis\n",
  "============================================\n\n",
  sep = ""
)



cat(
  "Input dataset: annotated candidate set\n\n"
)



cat(
  "Total unique candidate loci: ",
  nrow(targets),
  "\n\n",
  sep = ""
)



# ============================================================
# METHOD TOTALS
# ============================================================

method_totals <- targets %>%
  summarise(
    across(
      all_of(prediction_methods),
      ~ sum(
        .x,
        na.rm = TRUE
      )
    )
  )



cat(
  "Targets predicted by each method:\n"
)


print(
  method_totals
)



# ============================================================
# ASSIGN EXACT INTERSECTION GROUPS
# ============================================================

targets <- targets %>%
  mutate(
    
    prediction_group = case_when(
      
      CopraRNA &
        TargetRNA2 &
        IntaRNA ~
        "All three methods",
      
      
      CopraRNA &
        TargetRNA2 &
        !IntaRNA ~
        "CopraRNA + TargetRNA2",
      
      
      CopraRNA &
        !TargetRNA2 &
        IntaRNA ~
        "CopraRNA + IntaRNA",
      
      
      !CopraRNA &
        TargetRNA2 &
        IntaRNA ~
        "TargetRNA2 + IntaRNA",
      
      
      CopraRNA &
        !TargetRNA2 &
        !IntaRNA ~
        "CopraRNA only",
      
      
      !CopraRNA &
        TargetRNA2 &
        !IntaRNA ~
        "TargetRNA2 only",
      
      
      !CopraRNA &
        !TargetRNA2 &
        IntaRNA ~
        "IntaRNA only",
      
      
      TRUE ~
        "Not predicted"
      
    )
  )



# ============================================================
# INTERSECTION COUNTS
# ============================================================

intersection_counts <- targets %>%
  filter(
    prediction_group !=
      "Not predicted"
  ) %>%
  count(
    prediction_group,
    name = "number_of_targets"
  ) %>%
  arrange(
    desc(number_of_targets)
  )



cat(
  "\nExact prediction-intersection counts:\n"
)


print(
  intersection_counts
)



# ============================================================
# TARGETS PREDICTED BY ALL THREE METHODS
# ============================================================

all_three_targets <- targets %>%
  filter(
    CopraRNA &
      TargetRNA2 &
      IntaRNA
  ) %>%
  select(
    reference_locus,
    gene,
    annotation
  )



cat(
  "\nTargets predicted by all three methods:\n"
)


print(
  all_three_targets,
  n = Inf
)



# ============================================================
# SAVE PROCESSED TABLES
# ============================================================

intersection_file <- file.path(
  table_dir,
  "target_prediction_intersection_counts.csv"
)


groups_file <- file.path(
  table_dir,
  "targets_by_prediction_group.csv"
)


all_three_file <- file.path(
  table_dir,
  "targets_predicted_by_all_three_methods.csv"
)



write_csv(
  intersection_counts,
  intersection_file,
  na = ""
)



targets %>%
  select(
    candidate_id,
    reference_locus,
    gene,
    annotation,
    all_of(
      prediction_methods
    ),
    n_methods,
    prediction_group
  ) %>%
  arrange(
    prediction_group,
    gene,
    reference_locus
  ) %>%
  write_csv(
    groups_file,
    na = ""
  )



write_csv(
  all_three_targets,
  all_three_file,
  na = ""
)



# ============================================================
# PREPARE UPSET DATA
# ============================================================

targets_plot <- targets %>%
  filter(
    if_any(
      all_of(prediction_methods),
      identity
    )
  )



cat(
  "\nNumber of loci included in the UpSet plot: ",
  nrow(targets_plot),
  "\n",
  sep = ""
)



# ============================================================
# GENERATE UPSET PLOT
# ============================================================

upset_plot <- upset(
  
  targets_plot,
  
  intersect = prediction_methods,
  
  sort_intersections_by =
    "cardinality",
  
  sort_sets =
    FALSE,
  
  keep_empty_groups =
    FALSE,
  
  width_ratio =
    0.20,
  
  
  # ----------------------------------------------------------
  # Method colours
  # ----------------------------------------------------------
  
  queries = list(
    
    upset_query(
      set = "CopraRNA",
      colour =
        tool_colours["CopraRNA"],
      fill =
        tool_colours["CopraRNA"]
    ),
    
    upset_query(
      set = "TargetRNA2",
      colour =
        tool_colours["TargetRNA2"],
      fill =
        tool_colours["TargetRNA2"]
    ),
    
    upset_query(
      set = "IntaRNA",
      colour =
        tool_colours["IntaRNA"],
      fill =
        tool_colours["IntaRNA"]
    )
    
  ),
  
  
  # ----------------------------------------------------------
  # Intersection-size bars
  # ----------------------------------------------------------
  
  base_annotations = list(
    
    "Intersection size" =
      
      intersection_size(
        counts = TRUE
      ) +
      
      theme(
        
        axis.title.x =
          element_text(
            size = 10
          ),
        
        axis.title.y =
          element_text(
            size = 10
          ),
        
        axis.text =
          element_text(
            size = 9
          )
        
      )
  ),
  
  
  # ----------------------------------------------------------
  # Set-size bars
  # ----------------------------------------------------------
  
  set_sizes =
    
    upset_set_size(
      
      geom = geom_bar(
        
        aes(
          fill = group
        ),
        
        width = 0.75
        
      )
      
    ) +
    
    scale_fill_manual(
      
      values =
        tool_colours,
      
      guide =
        "none"
      
    ) +
    
    ylab(
      "Set size"
    ) +
    
    theme(
      
      axis.title.x =
        element_text(
          size = 10
        ),
      
      axis.title.y =
        element_text(
          size = 10
        ),
      
      axis.text =
        element_text(
          size = 9
        )
      
    )
  
) +
  
  labs(
    x =
      "Prediction method combination"
  )



# ============================================================
# ADD TITLE AND SUBTITLE
# ============================================================

upset_plot_final <- upset_plot +
  
  plot_annotation(
    
    title =
      figure_title,
    
    subtitle =
      figure_subtitle,
    
    theme = theme(
      
      text =
        element_text(
          family = "sans"
        ),
      
      plot.title =
        element_text(
          face = "bold",
          size = 14,
          hjust = 0
        ),
      
      plot.subtitle =
        element_text(
          size = 10,
          hjust = 0,
          margin = margin(
            b = 8
          )
        ),
      
      plot.margin =
        margin(
          t = 10,
          r = 15,
          b = 10,
          l = 10
        )
      
    )
  )



# ============================================================
# DISPLAY FIGURE
# ============================================================

print(
  upset_plot_final
)



# ============================================================
# SAVE FIGURE
# ============================================================

pdf_file <- file.path(
  figure_dir,
  "target_prediction_upset.pdf"
)


tiff_file <- file.path(
  figure_dir,
  "target_prediction_upset.tiff"
)



ggsave(
  
  filename =
    pdf_file,
  
  plot =
    upset_plot_final,
  
  width =
    figure_width,
  
  height =
    figure_height,
  
  units =
    "in"
  
)



ggsave(
  
  filename =
    tiff_file,
  
  plot =
    upset_plot_final,
  
  width =
    figure_width,
  
  height =
    figure_height,
  
  units =
    "in",
  
  dpi =
    figure_dpi,
  
  compression =
    "lzw"
  
)



# ============================================================
# COMPLETION SUMMARY
# ============================================================

cat(
  "\n============================================\n",
  "UpSet analysis complete\n",
  "============================================\n\n",
  sep = ""
)



cat(
  "Tables:\n",
  intersection_file,
  "\n",
  groups_file,
  "\n",
  all_three_file,
  "\n\n",
  sep = ""
)



cat(
  "Figures:\n",
  pdf_file,
  "\n",
  tiff_file,
  "\n",
  sep = ""
)

